"use client";

import { cn } from "@/lib/utils";
import type { Variants } from "motion/react";
import {
 LazyMotion,
 domMin,
 m,
 useAnimation,
 useReducedMotion,
} from "motion/react";
import {
 forwardRef,
 useCallback,
 useImperativeHandle,
 useRef,
 type HTMLAttributes,
} from "react";
export interface TornadoIconHandle {
 startAnimation: () => void;
 stopAnimation: () => void;
}

interface TornadoIconProps extends Omit<
 HTMLAttributes<HTMLDivElement>,
 | "color"
 | "onDrag"
 | "onDragStart"
 | "onDragEnd"
 | "onAnimationStart"
 | "onAnimationEnd"
 | "onAnimationIteration"
> {
 size?: number;
 duration?: number;
 isAnimated?: boolean;
 color?: string;
}

const TornadoIcon = forwardRef<TornadoIconHandle, TornadoIconProps>(
 (
  {
   onMouseEnter,
   onMouseLeave,
   className,
   size = 24,
   duration = 1,
   isAnimated = true,
   color,
   ...props
  },
  ref,
 ) => {
  const controls = useAnimation();
  const reduced = useReducedMotion();
  const isControlled = useRef(false);

  useImperativeHandle(ref, () => {
   isControlled.current = true;
   return {
    startAnimation: () =>
     reduced ? controls.start("normal") : controls.start("animate"),
    stopAnimation: () => controls.start("normal"),
   };
  });

  const handleEnter = useCallback(
   (e?: React.MouseEvent<HTMLDivElement>) => {
    if (!isAnimated || reduced) return;
    if (!isControlled.current) controls.start("animate");
    else onMouseEnter?.(e as any);
   },
   [controls, reduced, isAnimated, onMouseEnter],
  );

  const handleLeave = useCallback(
   (e: React.MouseEvent<HTMLDivElement>) => {
    if (!isControlled.current) {
     controls.start("normal");
    } else {
     onMouseLeave?.(e as any);
    }
   },
   [controls, onMouseLeave],
  );

  const lineVariants: Variants = {
   normal: { scaleX: 1 },
   animate: (i: number) => ({
    scaleX: [1, 0.55, 1],
    transition: {
     delay: i * 0.08 * duration,
     duration: 0.9 * duration,
     ease: "easeInOut",
     times: [0, 0.5, 1],
    },
   }),
  };

  return (
   <LazyMotion features={domMin} strict>
    <m.div
     className={cn("inline-flex items-center justify-center", className)}
     onMouseEnter={handleEnter}
     onMouseLeave={handleLeave}
     {...props}
     style={{ color, ...props.style }}
    >
     <m.svg
      xmlns="http://www.w3.org/2000/svg"
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="2"
      strokeLinecap="round"
      strokeLinejoin="round"
      animate={controls}
      initial="normal"
     >
      <m.path
       d="M21 4H3"
       custom={0}
       variants={lineVariants}
       style={{ transformBox: "view-box", originX: "12px", originY: "4px" }}
      />
      <m.path
       d="M18 8H6"
       custom={1}
       variants={lineVariants}
       style={{ transformBox: "view-box", originX: "12px", originY: "8px" }}
      />
      <m.path
       d="M19 12H9"
       custom={2}
       variants={lineVariants}
       style={{ transformBox: "view-box", originX: "14px", originY: "12px" }}
      />
      <m.path
       d="M16 16h-6"
       custom={3}
       variants={lineVariants}
       style={{ transformBox: "view-box", originX: "13px", originY: "16px" }}
      />
      <m.path
       d="M11 20H9"
       custom={4}
       variants={lineVariants}
       style={{ transformBox: "view-box", originX: "10px", originY: "20px" }}
      />
     </m.svg>
    </m.div>
   </LazyMotion>
  );
 },
);

TornadoIcon.displayName = "TornadoIcon";
export { TornadoIcon };
